#include "transport.hpp"
#include <iostream>
int main(){std::string line;while(std::getline(std::cin,line)){try{auto q=perekup::Json::parse(line);perekup::Transport t(q["cities"],q["cars"],q["home"]);perekup::Money cash=q.value("balance",10000000LL);t.garage=q["garage"];t.capacity=q.value("capacity",1);t.now=q.value("now",1000000.);t.balance=[&]{return cash;};t.spend=[&](perekup::Money n,const std::string&){if(n<0||n>cash)return false;cash-=n;return true;};perekup::Json out=perekup::Json::array();for(auto op:q["ops"]){auto name=op.value("op","");perekup::Json result=nullptr;if(name=="park")t.park(op["id"],op["city"],t.now);else if(name=="depart")result=t.depart(op["city"],op["mode"],op.value("id",0LL));else if(name=="ship")result=t.ship(op["id"]);else if(name=="tick"){t.now=op["now"];t.tick();}else if(name=="cash")cash=op["value"];else if(name=="capacity"){t.capacity=op["value"];t.rebalance();}else throw std::runtime_error("Unknown operation");out.push_back({{"result",result},{"state",t.state},{"balance",cash}});}std::cout<<out.dump()<<'\n';}catch(const std::exception& e){std::cout<<perekup::Json({{"error",e.what()}}).dump()<<'\n';}}}
